DO $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='core_management_api') THEN CREATE ROLE core_management_api NOLOGIN;END IF;
END $$;
GRANT USAGE ON SCHEMA public TO core_management_api;
GRANT EXECUTE ON FUNCTION public.verify_platform_credential_v1(text),public.core_platform_authorize_v1(jsonb,text),public.credit_wallet(uuid,text,text,numeric,text,integer,timestamptz,text[],text[]) TO core_management_api;
GRANT SELECT ON supplier_brands,upstream_accounts,channels,models,routes,cost_versions,billing_prices,billing_tariffs,projects,api_keys,financial_vouchers,upstream_funding_operations,upstream_account_balances TO core_management_api;
GRANT INSERT ON supplier_brands,upstream_accounts,channels,models,routes,cost_versions,billing_prices,billing_tariffs,projects,api_keys,financial_vouchers,upstream_funding_operations,upstream_account_balances,upstream_journals,upstream_entries,upstream_audit_events,audit_events TO core_management_api;
GRANT UPDATE ON supplier_brands,channels,routes,billing_tariffs,upstream_account_balances TO core_management_api;
GRANT EXECUTE ON FUNCTION public.exact_billing_price(jsonb,jsonb) TO core_management_api;
GRANT UPDATE(id) ON financial_vouchers TO core_management_api;
GRANT UPDATE(id) ON upstream_accounts TO core_management_api;
GRANT SELECT ON upstream_journals,upstream_entries TO core_management_api;
GRANT UPDATE(id) ON supplier_brands TO core_management_api;
GRANT EXECUTE ON FUNCTION public.configure_wallet_credit(uuid,text,text,numeric,numeric),public.refund_billing_charge(uuid,numeric,text,text),public.adjust_billing_charge(uuid,numeric,text,text),public.wallet_freeze_reason(boolean,boolean,numeric,numeric,numeric) TO core_management_api;
GRANT SELECT ON wallets,wallet_lots,money_journal,wallet_disputes,billing_resolutions,billing_holds,billing_charges,gateway_requests,attempts TO core_management_api;
GRANT UPDATE(policy,manual_frozen,freeze_reason,evidence_disputed) ON wallets TO core_management_api;
GRANT UPDATE(next_reconcile_at,reconcile_until) ON billing_holds TO core_management_api;
GRANT INSERT ON billing_resolutions TO core_management_api;
GRANT UPDATE(state,revision) ON upstream_accounts TO core_management_api;
GRANT SELECT,INSERT ON reconciliations TO core_management_api;
GRANT SELECT ON upstream_holds TO core_management_api;
GRANT SELECT,INSERT ON organizations,principals TO core_management_api;
GRANT UPDATE(enabled,rpm,tpm,concurrency) ON organizations TO core_management_api;
GRANT UPDATE(enabled,role,rpm,tpm,concurrency) ON principals TO core_management_api;
GRANT UPDATE(name,enabled,rpm,tpm,concurrency,billing_currency) ON projects TO core_management_api;
GRANT UPDATE(enabled,models,operations,expires_at,allowed_cidrs,role,rpm,tpm,concurrency) ON api_keys TO core_management_api;
GRANT UPDATE(enabled,operations,max_output_tokens,routing_strategy) ON models TO core_management_api;
